#!/usr/bin/env bash
#
# Wingman PreToolUse guard — protects files that must never be written by hand.
#
# Runs alongside env-guard.sh (which blocks .env* edits). Two classes here:
#
# 1. GENERATED files. Hand-editing them means the next `npm run context:gen`
#    silently discards the edit — the worst kind of loss, because it looks like
#    it worked.
#
# 2. HAND-GRADED files (`*.MARKED.md`, `*.gradesheet.html`). These carry
#    Sebastian's own ✓/✗/rewrite marks on card voice — the human reward signal for
#    the entire voice track, and the one thing in this repo that cannot be
#    regenerated at any price. `scripts/voice-batch.mjs` writes into that same
#    directory by absolute path, so one careless regeneration could take months of
#    judgement with it. Protected by a machine, not by convention.
#
# Reads the PreToolUse JSON on stdin; exit 2 blocks the call and tells Claude why.

input=$(cat)
file=$(printf '%s' "$input" | node -e 'let d="";process.stdin.on("data",c=>d+=c).on("end",()=>{try{const j=JSON.parse(d);const ti=j.tool_input||{};process.stdout.write(ti.file_path||ti.path||"")}catch(e){process.stdout.write("")}})')

[ -z "$file" ] && exit 0
base=$(basename "$file" 2>/dev/null)

case "$file" in
  */context/STATE.md|context/STATE.md)
    echo "BLOCKED: context/STATE.md is GENERATED by scripts/context-gen.mjs. A hand edit is discarded on the next run. Change the generator instead, then: npm run context:gen" >&2
    exit 2 ;;
  *"01 - Build Log/Build Log.md")
    echo "BLOCKED: 'Build Log.md' is GENERATED by scripts/context-gen.mjs (it indexes all 41 dated logs). To change a session summary, edit that session's YYYY-MM-DD.md, or the HAND_WRITTEN map in the generator, then: npm run context:gen" >&2
    exit 2 ;;
esac

case "$base" in
  *.MARKED.md|*.gradesheet.html)
    echo "BLOCKED: '$base' holds Sebastian's hand-written grades — the one artifact in this repo that cannot be regenerated. If a new batch is genuinely needed, write it to a NEW filename and leave this one untouched." >&2
    exit 2 ;;
esac

exit 0
